// =========================================================================
// Title: Trailing the Twinkling Tunnelwisp (Visual)
// Gyroid logic adapted from: Paul Karlik
// 
// License: CC0 1.0 Universal (Public Domain Dedication)
//          https://creativecommons.org/publicdomain/zero/1.0/
//
// Note: Adapted for the "Surfaces Explorer" engine.
// =========================================================================

float g(vec4 p, float s) {
  return abs(dot(sin(p *= s), cos(p.zxwy)) - 1.0) / s;
}

void mainImage(out vec4 O, vec2 C) {
  float d = 0.0, z = 0.0, s = 0.0, T = iTime;
  vec4 o = vec4(0.0), q, p, U = vec4(2.0, 1.0, 0.0, 3.0);
  vec2 r = iResolution.xy;

  // FIX: Loop convertito in INT standard per driver Vulkan/SPIR-V
  for (int i = 0; i < 79; i++) {
    z += d + 5e-4;
    q = vec4(normalize(vec3(C - 0.5 * r, r.y)) * z, 0.2);
    q.z += T / 3e1;
    s = q.y + 0.1;
    q.y = abs(s);
    p = q;
    p.y -= 0.11;
    p.xy *= mat2(cos(11.0 * U.zywz - 2.0 * p.z));
    p.y -= 0.2;
    d = abs(g(p, 8.0) - g(p, 24.0)) / 4.0;

    // FIX: Somma con vec4(1.0) esplicito
    p = vec4(1.0) + cos(0.7 * U + 5.0 * q.z);
    o += (s > 0.0 ? 1.0 : 0.1) * p.w * p / max(s > 0.0 ? d : d * d * d, 5e-4);
  }

  // FIX: Prevenzione Divisione per Zero (length(q.xy) + 1e-4)
  o += (1.4 + sin(T) * sin(1.7 * T) * sin(2.3 * T)) * 1e3 * U / (length(q.xy) + 1e-4);

  // FIX: Clamp finale per evitare overflow di luminosità
  O = clamp(tanh(o / 1e5), 0.0, 1.0);
}

